  v.put("receiptCorrections",db.list(ReceiptCorrection.class,"from ReceiptCorrection where bookId=?1 order by sequence",b.id).stream().filter(c->manage||(db.find(Report.class,c.reportId).userId.equals(a.userId())||a.userId().equals(db.find(Report.class,c.reportId).processedBy))).map(c->{var m=new LinkedHashMap<String,Object>();m.put("id",c.id);m.put("reportId",c.reportId);m.put("revisionId",c.revisionId);m.put("amount",c.amount);m.put("actualReceivedAt",c.actualReceivedAt);m.put("reason",c.reason);m.put("createdAt",c.createdAt);m.put("createdBy",c.createdBy);return m;}).toList());
  v.put("extensions",db.list(Extension.class,"from RequestExtension where bookId=?1 order by createdAt,id",b.id).stream().filter(x->all||db.find(Request.class,x.requestId).userId.equals(a.userId())).map(x->{var m=new LinkedHashMap<String,Object>();m.put("id",x.id);m.put("requestId",x.requestId);m.put("previousDeadline",x.previousDeadline);m.put("deadline",x.deadline);m.put("reason",x.reason);m.put("createdBy",x.createdBy);m.put("createdAt",x.createdAt);return m;}).toList());
  var visibleRounds=ownRounds(a,event,b);v.put("expenses",expenses(b).stream().filter(x->all||visibleRounds.contains(x.roundId.toString())).map(x->{var m=new LinkedHashMap<String,Object>();m.put("id",x.id);m.put("roundId",x.roundId);m.put("revisionId",x.revisionId);m.put("title",x.title);m.put("amount",x.amount);m.put("paidByUserId",currentPayer(b,x));m.put("originalPaidByUserId",x.paidByUserId);m.put("fundingStatus",unclassified(b).contains(x.id)?"UNKNOWN":"CLASSIFIED");m.put("fundings",fundings(b).stream().filter(f->f.expenseId.equals(x.id)).map(f->{var part=new LinkedHashMap<String,Object>();part.put("paidByUserId",f.paidByUserId);part.put("source",f.source);part.put("amount",f.amount);part.put("actualPaidAt",f.actualPaidAt);return part;}).toList());m.put("evidence",x.evidence);m.put("evidenceStatus",x.evidence==null?"NO_EVIDENCE":x.evidence.startsWith("file:")?"ATTACHED":"NOTE");m.put("createdAt",x.createdAt);m.put("createdBy",x.createdBy);return m;}).toList());
  v.put("revisions",db.list(Revision.class,"from FinanceRevision where bookId=?1 order by createdAt,id",b.id).stream().map(r->{var m=new LinkedHashMap<String,Object>();m.put("id",r.id);m.put("reason",r.reason);m.put("createdAt",r.createdAt);m.put("createdBy",r.createdBy);m.put("snapshot",all?r.snapshot:json.writeValueAsString(ownCalculation(a,event,json.readValue(r.snapshot,SettlementCalculator.EventResult.class))));m.put("afterSnapshot",r.afterSnapshot==null?null:all?r.afterSnapshot:json.writeValueAsString(ownCalculation(a,event,json.readValue(r.afterSnapshot,SettlementCalculator.EventResult.class))));return m;}).toList());
  v.put("refunds",refunds(b).stream().filter(r->all||r.userId.equals(a.userId())||a.userId().equals(r.sentBy)).map(r->{var m=new LinkedHashMap<String,Object>();m.put("id",r.id);m.put("userId",r.userId);m.put("amount",r.amount);m.put("sentAmount",r.sentAmount);m.put("status",r.status);m.put("requestedAt",r.requestedAt);m.put("sentAt",r.sentAt);m.put("sentBy",r.sentBy);m.put("confirmedAt",r.confirmedAt);if(manage||r.userId.equals(a.userId()))m.put("transactionReference",r.transactionReference);return m;}).toList());
  v.put("disputes",db.list(Dispute.class,"from FinanceDispute where bookId=?1 order by createdAt,id",b.id).stream().filter(d->all||d.userId.equals(a.userId())||a.userId().equals(d.counterpartyId)).map(d->disputeView(d,manage||d.userId.equals(a.userId())||a.userId().equals(d.counterpartyId))).toList());
  v.put("participationChanges",db.list(ParticipationChange.class,"from ParticipationChange where eventId=?1 order by createdAt,id",event).stream().filter(x->all||db.find(Participation.class,x.participationId).userId.equals(a.userId())).map(x->{var m=new LinkedHashMap<String,Object>();m.put("id",x.id);m.put("participationId",x.participationId);m.put("revisionId",x.revisionId);m.put("oldStatus",x.oldStatus);m.put("newStatus",x.newStatus);m.put("oldFee",x.oldFee);m.put("newFee",x.newFee);m.put("feeVersion",x.feeVersion);m.put("waivedReason",x.waivedReason);m.put("reason",x.reason);m.put("createdAt",x.createdAt);m.put("createdBy",x.createdBy);return m;}).toList());
  var names=new LinkedHashMap<UUID,Object>();var users=new HashSet<UUID>();for(var p:participants(event))if(all||p.userId.equals(a.userId()))users.add(p.userId);for(var f:fundings(b))if(all||a.userId().equals(f.paidByUserId))users.add(f.paidByUserId);for(var expense:expenses(b))if(expense.paidByUserId!=null&&(all||a.userId().equals(expense.paidByUserId))&&unclassified(b).contains(expense.id))users.add(expense.paidByUserId);for(var r:reports(b))if(manage||a.userId().equals(r.userId)||a.userId().equals(r.processedBy)){users.add(r.userId);if(r.processedBy!=null)users.add(r.processedBy);}if(all||e.hostId.equals(a.userId()))users.add(e.hostId);for(var user:users){var m=db.member(e.clubId,user);boolean named=m!=null&&m.nickname!=null&&Set.of("ACTIVE","LEFT","EXPELLED").contains(m.status);names.put(user,Map.of("nickname",named?m.nickname:db.find(Account.class,user).nickname,"departed",m!=null&&Set.of("LEFT","EXPELLED").contains(m.status)));}v.put("names",names);var calc=calculation(b);v.put("calculation",all?calc:ownCalculation(a,event,calc));var fs=reconcile(b,baseCalculation(b));v.put("funding",all?fs:new FundingSnapshot(fs.eventId(),fs.ready(),fs.unclassifiedExpenses().stream().filter(id->visibleRounds.contains(db.find(Expense.class,id).roundId.toString())).toList(),fs.positions().stream().filter(p->p.userId().equals(a.userId())).toList(),fs.custody().stream().filter(p->p.actorId().equals(a.userId())).toList(),fs.factsAvailable()));v.put("permissions",Map.of("manageSettlement",manage,"canCreateDispute",events.historical(event,a.userId()),"canRequestOwnRefund",canRequestOwnRefund(b,e,a.userId())));return v;
